args<-commandArgs(TRUE);P<-normalizePath(args[1]);W<-file.path(P,'work/2026-10-29-remaining-maps/gibbs-geotopo');library(sf);library(ggplot2);library(jsonlite);set.seed(20261029)
for(mid in c('ASF-V05','ASF-V08'))dir.create(file.path(W,mid),showWarnings=FALSE)
pd<-file.path(P,'results/plot_data');world<-map_data('world');saveRDS(world,file.path(W,'world-polygons.rds'));write.csv(world,file.path(pd,'asf0508_geographic_basemap_20261029.csv'),row.names=FALSE)
# Geographic polygons are genuine; group membership is independently simulated, with no movement analysis or epidemiological inference.
g<-st_read(file.path(W,'gadm41_CHN_2.json'),quiet=TRUE);g<-st_make_valid(g);pts<-st_coordinates(st_centroid(st_transform(g,3857)));pts<-st_coordinates(st_transform(st_as_sf(data.frame(x=pts[,1],y=pts[,2]),coords=c('x','y'),crs=3857),4326));eligible<-which(pts[,1]>103 &pts[,1]<125&pts[,2]>21&pts[,2]<42);ix<-sample(eligible,125);g$synthetic_group<-NA_character_;g$synthetic_group[ix]<-sample(rep(paste('Group',LETTERS[1:4]),length.out=125));g$synthetic_value<-NA_real_;g$synthetic_value[ix]<-runif(125,.1,1);write.csv(data.frame(GID_2=g$GID_2,province=g$NAME_1,region=g$NAME_2,synthetic_group=g$synthetic_group,synthetic_value=g$synthetic_value),file.path(pd,'asf05_synthetic_prefecture_groups_20261029.csv'),row.names=FALSE);saveRDS(g,file.path(W,'ASF-V05/map-data.rds'))
q<-list(stem='asf05_gibbs_map_structure_simulated_20261029',width_mm=183,height_mm=125,simulation=TRUE,seed=20261029,data_origin='User-authorized structural simulation on real GADM4.1 prefecture polygons.125 arbitrary category assignments and values; not author clusters or observations. Fig1d map structure only; source panels a-c/e excluded.',crs='EPSG:4326 source, EPSG:3857 render',n_geographic_regions=nrow(g),n_simulated_regions=125,source='https://geodata.ucdavis.edu/gadm/gadm4.1/json/gadm41_CHN_2.json',exact_original_data=FALSE);write_json(q,file.path(W,'ASF-V05/input-qc.json'),pretty=T,auto_unbox=T)
# Abstract directed graphs on geographic country centers, no pathogen, variants, time or modeled spread.
nodes<-data.frame(id=c('MA','DZ','TN','EG','SN','ML','NE','GH','NG','CM','CD','AO','ET','KE','UG','TZ','ZM','ZW','BW','ZA'),country=c('Morocco','Algeria','Tunisia','Egypt','Senegal','Mali','Niger','Ghana','Nigeria','Cameroon','DR Congo','Angola','Ethiopia','Kenya','Uganda','Tanzania','Zambia','Zimbabwe','Botswana','South Africa'),lon=c(-6,3,10,30,-14,-4,9,-1,8,12,23,18,39,38,32,35,28,30,24,25),lat=c(32,28,34,27,14,17,17,8,9,6,-3,-12,9,1,1,-6,-13,-19,-22,-29),origin_region=c(rep('Northern Africa',4),rep('Western Africa',6),'Southern Africa','Southern Africa',rep('Eastern Africa',4),rep('Southern Africa',4)))
ns<-c(50,26,58,19,15);edges<-list();for(i in 1:5){pool<-expand.grid(origin=nodes$id,destination=nodes$id,stringsAsFactors=F);pool<-pool[pool$origin!=pool$destination,];a<-sample(seq_len(nrow(pool)),ns[i]);d<-pool[a,];d$network<-paste('Network',LETTERS[i]);d$synthetic_weight<-sample(1:100,nrow(d),replace=T);o<-match(d$origin,nodes$id);t<-match(d$destination,nodes$id);d$x<-nodes$lon[o];d$y<-nodes$lat[o];d$xend<-nodes$lon[t];d$yend<-nodes$lat[t];d$origin_region<-nodes$origin_region[o];edges[[i]]<-d};e<-do.call(rbind,edges);cnt<-aggregate(destination~network+origin,e,length);names(cnt)[3]<-'connections';nn<-merge(expand.grid(network=paste('Network',LETTERS[1:5]),id=nodes$id,stringsAsFactors=F),nodes,by='id');nn<-merge(nn,cnt,by.x=c('network','id'),by.y=c('network','origin'),all.x=T);nn$connections[is.na(nn$connections)]<-0;saveRDS(list(nodes=nn,edges=e,world=world),file.path(W,'ASF-V08/map-data.rds'));write.csv(e,file.path(pd,'asf08_synthetic_network_edges_20261029.csv'),row.names=F);write.csv(nn,file.path(pd,'asf08_synthetic_network_nodes_20261029.csv'),row.names=F)
q<-list(stem='asf08_tegally_map_structure_simulated_20261029',width_mm=183,height_mm=56,simulation=TRUE,seed=20261029,data_origin='User-authorized abstract-network structural simulation:5 independent arbitrary directed networks on20 approximate country-center coordinates and real world outlines. No pathogen observations, genomes, ancestral-state or transmission model; not source Fig4C findings. Source Fig4A/B excluded.',crs='EPSG:4326 geographic context, fixed equal coordinate aspect',n_nodes_per_network=20,n_simulated_edges=nrow(e),edges_per_network=ns,exact_original_data=FALSE);write_json(q,file.path(W,'ASF-V08/input-qc.json'),pretty=T,auto_unbox=T)
